    useState<AvailableReportCard | null>(null);

  // Table Sorting & Pagination
  const [sortField, setSortField] =
    useState<keyof DoctorSummaryPerformanceRecord>("revenue");
  const [sortOrder, setSortOrder] = useState<"asc" | "desc">("desc");

  // Refresh handler
  const handleRefresh = () => {
    setIsRefreshing(true);
    setTimeout(() => {
      setIsRefreshing(false);
    }, 600);
  };

  // Reset filters handler
  const handleResetFilters = () => {
    setSearchQuery("");
    setBranchFilter("Main Branch");
    setDeptFilter("All Departments");
    setDoctorFilter("All Doctors");
    setDateRangeFilter("Today");
    setTypeFilter("All Types");
    setStatusFilter("All Statuses");
  };

  // Filtered reports
  const filteredReports = useMemo(() => {
    return AVAILABLE_REPORTS_DATA.filter((rep) => {
      const matchesSearch =
        rep.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        rep.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
        rep.category.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesType =
        typeFilter === "All Types" ||
        rep.category.toLowerCase() === typeFilter.toLowerCase();
      return matchesSearch && matchesType;
    });
  }, [searchQuery, typeFilter]);

  // Sorted doctors for the performance table
  const sortedDoctors = useMemo(() => {
    return [...DOCTOR_PERFORMANCE_SUMMARY_DATA].sort((a, b) => {
      const aVal = a[sortField];
      const bVal = b[sortField];

      if (typeof aVal === "string" && typeof bVal === "string") {
        return sortOrder === "asc"
          ? aVal.localeCompare(bVal)
          : bVal.localeCompare(aVal);
      }

      if (typeof aVal === "number" && typeof bVal === "number") {
        return sortOrder === "asc"
          ? aVal - bVal
          : bVal - aVal;
      }

      return 0;
    });
  }, [sortField, sortOrder]);



  const handleSort = (field: keyof DoctorSummaryPerformanceRecord) => {
    if (sortField === field) {
      setSortOrder(sortOrder === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortOrder("desc");
    }
  };

  // Formatting helpers
  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-IN", {
      style: "currency",
      currency: "INR",
      maximumFractionDigits: 0,
    }).format(amount);
  };

